import {readFileSync,writeFileSync,realpathSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {dirname,resolve,isAbsolute,posix} from 'node:path';
import {pathToFileURL} from 'node:url';
import {Worker,isMainThread,workerData} from 'node:worker_threads';
import {runTemplateSteps,runCheckerSteps} from "/Users/ilyagulya/Projects/My/bend/evals/checker_core_step_runtime.mjs";
const hash=path=>createHash('sha256').update(readFileSync(path)).digest('hex'),tag=value=>typeof value?.$==='string'?value.$.split('.').at(-1):null;
const items=value=>{const out=[];while(tag(value)==='Con'){out.push(value.head);value=value.tail;}if(tag(value)!=='Nil')throw Error('Malformed native list');return out;};
const list=values=>values.reduceRight((tail,head)=>({$:'Con',head,tail}),{$:'Nil'});
const fuelEnd=Object.freeze({$:'FeedbackFuelEnd'}),fuelPrototype={get tail(){return fuel(this.remaining-1);}};
function fuel(remaining){if(remaining===0)return fuelEnd;const node=Object.create(fuelPrototype);node.$='FeedbackFuelCell';node.remaining=remaining;return node;}
function verify(request){for(const [path,digest]of Object.entries({...request.inputs,...request.pins}))if(realpathSync(path)!==path||hash(path)!==digest)throw Error('Pinned input drift '+path);}
async function screen(requestPath,reportPath){
 const request=JSON.parse(readFileSync(requestPath,'utf8'));verify(request);
 const report={schemaVersion:1,status:'RUNNING',diagnosticOnly:true,acceptanceEvidence:false,compilerAccepted:false,byteFixedpoint:false,role:request.role,scope:'Actual selfhost checker image with identical accepted R12 parser/expander on the unchanged frozen root. No host constructor adaptation; one unprofiled diagnostic sample, not acceptance.',request:requestPath,requestSha256:hash(requestPath),parserImage:request.parserImage,checkerImage:request.checkerImage,root:request.root,sourceSha256:hash(request.root),runtime:{execPath:process.execPath,versions:process.versions,execArgv:process.execArgv},phases:[],stepCounts:{}};
 const save=()=>writeFileSync(reportPath,JSON.stringify(report,null,2)+String.fromCharCode(10));save();
 const phase=async(name,action)=>{const start=performance.now(),cpu=process.cpuUsage();const result=await action();const used=process.cpuUsage(cpu);report.phases.push({phase:name,elapsedMs:performance.now()-start,userCpuMs:used.user/1000,systemCpuMs:used.system/1000,memoryEnd:process.memoryUsage()});save();return result;};
 const {api,checker}=await phase('startup',async()=>{
  const parserURL=pathToFileURL(request.parserImage.path).href+'?g30-role=parser',checkerURL=pathToFileURL(request.checkerImage.path).href;
  const api=(await import(parserURL)).default,checker=(await import(checkerURL)).default;
  if(api===checker)throw Error('Screen requires distinct parser/checker module instances in BOTH lanes');
  report.moduleResidency={parserURL,checkerURL,distinctAPI:true,moduleInstances:2,policy:'Same parser URL role in both lanes; no control-only module-cache alias.'};
  return {api,checker};
 });
 for(const key of ['check_expanded_start','inspect_checked_start','checker_step'])if(typeof checker[key]!=='function')throw Error('Checker ABI incomplete '+key);
 let modules=[];await phase('load-parse',()=>{
  const seen=new Map(),active=new Set(),observed=new Set();
  const observe=path=>{const real=realpathSync(path);if(!Object.hasOwn(request.inputs,real))throw Error('Unexpected input '+real);observed.add(real);return real;};
  const namespace=(scope,path)=>path==='Base'?'':posix.normalize(isAbsolute(path)?path.replace(/\.bend$/,''):posix.dirname(scope)+'/'+path.replace(/\.bend$/,''));
  const visit=(file,scope)=>{const real=observe(file);if(active.has(real))throw Error('Import cycle');if(seen.has(real)){if(seen.get(real)!==scope)throw Error('Namespace conflict');return;}seen.set(real,scope);active.add(real);
   const parsed=api.parse_with_fuel(fuel(8000000),real,readFileSync(real,'utf8'));if(tag(parsed)!=='FeedbackComplete'||tag(parsed.value.result)!=='ParseSuccess')throw Error('Own parser rejected '+real);const module=parsed.value.result.module;
   for(const top of items(module.declarations))if(tag(top)==='DefTop'&&tag(top.definition.body)==='DefImports')for(const path of items(top.definition.body.paths))if(path.endsWith('.js'))observe(resolve(dirname(real),path));
   for(const imported of items(module.imports)){const path=imported.path;if(path.endsWith('.js'))observe(resolve(dirname(real),path));else if(!path.endsWith('.c'))visit(path==='Base'?resolve(request.repository,'bend2/base.bend'):resolve(dirname(real),path),namespace(scope,path));}
   modules.push(api.parsed_module(scope,module));active.delete(real);
  };visit(request.root,'');if(observed.size!==Object.keys(request.inputs).length)throw Error('Own parser omitted frozen input');report.moduleCount=seen.size;modules=list(modules);
 });
 let expanded=await phase('expand',()=>runTemplateSteps({...api,expand_modules_start:input=>{modules=undefined;return api.expand_modules_start(input);}},modules,{onFinish(_,steps){report.stepCounts.expand=steps;}}));
 if(tag(expanded)!=='ExpandSuccess')throw Error('Own expansion failed');
 const checked=await phase('check',()=>runCheckerSteps({...checker,check_expanded_start:input=>{expanded=undefined;return checker.check_expanded_start(input);}},expanded.modules,{onFinish(_,steps){report.stepCounts.check=steps;}}));
 if(tag(checked)!=='CheckSuccess')throw Error('Own checking failed '+JSON.stringify(checked));
 await phase('storage',()=>{
  const source=checked.program.source,words=source.words;if((!Array.isArray(words)&&!(words instanceof Uint32Array))||!Array.isArray(source.counts))throw Error('Unknown word-tape carrier');
  const used=source.counts[6],capacity=source.counts[7];if(words.length!==capacity||used>capacity)throw Error('Source word capacity mismatch');
  const digest=createHash('sha256'),chunk=new Uint32Array(16384),bytes=new Uint8Array(chunk.buffer);let maxWord=0;
  for(let offset=0;offset<capacity;offset+=chunk.length){const count=Math.min(chunk.length,capacity-offset);for(let i=0;i<count;i++){const value=words[offset+i];if(!Number.isInteger(value)||value<0||value>4294967295)throw Error('Non-U32 word');chunk[i]=value;if(value>maxWord)maxWord=value;}digest.update(count===chunk.length?bytes:bytes.subarray(0,count*4));}
  report.storage={sourceNodeUsed:source.counts[0],sourceNodeCapacity:source.counts[1],sourceNodeCarrier:Array.isArray(source.nodes)?"Array":typeof source.nodes,sourceWordUsed:used,sourceWordCapacity:capacity,sourceWordDepth:source.depths[3],sourceCounts:source.counts.slice(0,12),carrier:Array.isArray(words)?'Array':'Uint32Array',byteLength:words instanceof Uint32Array?words.byteLength:null,sha256:digest.digest('hex'),maxWord,hashEncoding:'host-little-endian-u32',limitations:['Final source tape only; no transient peak-capacity claim.','64-KiB hash scratch is allocated only after the measured check phase.','No inspector, profiling, or heap snapshot is enabled.']};
 });verify(request);report.status='G30_ACTUAL_SELFHOST_SCREEN_PASS';save();console.log(JSON.stringify({status:report.status,role:report.role,phases:report.phases.map(({phase,elapsedMs,memoryEnd})=>({phase,elapsedMs,memoryEnd})),stepCounts:report.stepCounts,storage:report.storage}));
}
if(isMainThread){const [requestPath,reportPath]=process.argv.slice(2);if(!requestPath||!reportPath)throw Error('Expected request/report');const worker=new Worker(new URL(import.meta.url),{workerData:{requestPath,reportPath},resourceLimits:{stackSizeMb:256,maxOldGenerationSizeMb:6144,maxYoungGenerationSizeMb:128}});worker.on('error',error=>{console.error(error);process.exitCode=1;});worker.on('exit',code=>{if(code!==0)process.exitCode=code;});}else await screen(workerData.requestPath,workerData.reportPath);
